<?php
/** По делу v1.8.0. Схема v1.7, транзакции по клиенту, точные минуты. */
namespace Markitan\Podelu;
if(!defined('B_PROLOG_INCLUDED')||B_PROLOG_INCLUDED!==true){die();}
use Bitrix\Main\Loader;use Bitrix\Main\Application;use Bitrix\Main\Type\DateTime;use Bitrix\Main\Config\Option;use Bitrix\Highloadblock\HighloadBlockTable;
require_once __DIR__.'/Policy.php';
final class Repository {
 private $classes=[];private $schema;private $ready=false;
 public function __construct(){if(!Loader::includeModule('highloadblock'))throw new \RuntimeException('Нет highloadblock.');$this->schema=require __DIR__.'/Schema.php';}
 public function table(string $t): string {if(isset($this->classes[$t]))return $this->classes[$t];if(!isset($this->schema[$t]))throw new \RuntimeException('Неизвестная сущность.');$d=$this->schema[$t];$h=HighloadBlockTable::getList(['filter'=>['=NAME'=>$d['name']],'limit'=>1])->fetch();if(!$h||$h['TABLE_NAME']!==$d['table'])throw new \RuntimeException('Нет '.$d['name']);$e=HighloadBlockTable::compileEntity($h);foreach(array_keys($d['fields']) as $f)if(!$e->hasField($f))throw new \RuntimeException('Нет поля '.$f);return $this->classes[$t]=$e->getDataClass();}
 public function ready(): void {if($this->ready)return;if(Option::get('markitan.podelu','schema_version','')!=='1.8.0')throw new \RuntimeException('Нужна миграция v1.8.0.');foreach(array_keys($this->schema) as $t)$this->table($t);$this->ready=true;}
 public function rows(string $t,array $f=[],array $o=['ID'=>'ASC']): array {$c=$this->table($t);return $c::getList(['filter'=>$f,'order'=>$o])->fetchAll();}
 public function find(string $t,int $id): ?array {if($id<1)return null;$c=$this->table($t);return $c::getByPrimary($id)->fetch()?:null;}
 private function write(string $t,array $v,int $id=0): int {$c=$this->table($t);$r=$id?$c::update($id,$v):$c::add($v);if(!$r->isSuccess())throw new \RuntimeException(implode('; ',$r->getErrorMessages()));return $id?:(int)$r->getId();}
 private function remove(string $t,int $id): void {$c=$this->table($t);$r=$c::delete($id);if(!$r->isSuccess())throw new \RuntimeException(implode('; ',$r->getErrorMessages()));}
 private function stamp(int $u): array {return ['UF_CREATED_AT'=>new DateTime(),'UF_CREATED_BY'=>$u,'UF_XML_ID'=>bin2hex(random_bytes(16))];}
 private function tx(int $cid,callable $fn){$this->ready();$c=Application::getConnection();$c->startTransaction();try{if(!$c->query('SELECT ID FROM mc_podelu_clients WHERE ID = '.(int)$cid.' FOR UPDATE')->fetch())throw new \InvalidArgumentException('Клиент не найден.');$v=$fn();$c->commitTransaction();return $v;}catch(\Throwable $e){$c->rollbackTransaction();throw $e;}}
 public function addClient(string $n,string $s,string $note,bool $active,int $u): int {return $this->write('clients',['UF_NAME'=>$n,'UF_SITE'=>$s,'UF_COMMENT'=>$note,'UF_ACTIVE'=>$active?1:0]+$this->stamp($u));}
 public function addDirection(string $n): int {foreach($this->rows('directions') as $d)if(mb_strtolower(trim($d['UF_NAME']))===mb_strtolower($n))throw new \InvalidArgumentException('Направление уже есть.');return $this->write('directions',['UF_NAME'=>$n,'UF_ACTIVE'=>1,'UF_XML_ID'=>bin2hex(random_bytes(16))]);}
 public static function ids(string $json): array {$v=json_decode($json,true);if(!is_array($v))throw new \RuntimeException('Повреждены направления.');foreach($v as $n)if(!is_int($n)||$n<1)throw new \RuntimeException('Некорректное направление.');return array_values(array_unique($v));}
 private function dirs(array $ids): void {foreach($ids as $id)if(!$this->find('directions',$id))throw new \InvalidArgumentException('Направление не найдено.');}
 public function presets(bool $active=false): array {return $this->rows('presets',$active?['=UF_ACTIVE'=>1]:[],['UF_SORT'=>'ASC','ID'=>'ASC']);}
 public function savePreset(int $id,string $n,string $title,string $desc,int $dir,array $ds,bool $group,bool $favorite,bool $active,int $sort,string $icon): int {if($dir)$this->dirs([$dir]);if($id&&!$this->find('presets',$id))throw new \InvalidArgumentException('Шаблон не найден.');$v=['UF_NAME'=>$n,'UF_TITLE'=>$title,'UF_DESCRIPTION'=>$desc,'UF_DIRECTION'=>$dir,'UF_DURATIONS'=>json_encode(array_values($ds)),'UF_GROUP'=>$group?1:0,'UF_FAVORITE'=>$favorite?1:0,'UF_ACTIVE'=>$active?1:0,'UF_SORT'=>$sort,'UF_ICON'=>$icon];if(!$id)$v['UF_XML_ID']=bin2hex(random_bytes(16));return $this->write('presets',$v,$id);}
 public function packages(int $cid,string $m,bool $skipped=false): array {$bs=$this->rows('packages',['=UF_CLIENT'=>$cid]);if(!$bs)return [];$ids=array_map(static function($p){return (int)$p['ID'];},$bs);$rs=[];foreach($this->rows('rules',['@UF_PACKAGE'=>$ids,'<=UF_MONTH'=>$m]) as $r)$rs[(int)$r['UF_PACKAGE']][]=$r;$ss=[];foreach($this->rows('skips',['@UF_PACKAGE'=>$ids,'=UF_MONTH'=>$m]) as $r)$ss[(int)$r['UF_PACKAGE']]=true;$out=[];foreach($bs as $b){$p=Policy::effective($b,$m,$rs[(int)$b['ID']]??[]);if(!$p)continue;$p['IS_SKIPPED']=isset($ss[(int)$b['ID']]);if($p['IS_SKIPPED']&&!$skipped)continue;$p['DIRECTION_IDS']=self::ids((string)$p['UF_DIRECTION_IDS']);$out[]=$p;}return $out;}
 private function effective(int $id,int $cid,string $m): ?array {foreach($this->packages($cid,$m) as $p)if((int)$p['ID']===$id)return $p;return null;}
 public function entries(string $m='',int $cid=0,int $task=0): array {$f=[];if($m!==''){$f['>=UF_DATE']=$m.'-01';$f['<=UF_DATE']=$m.'-31';}if($cid)$f['=UF_CLIENT']=$cid;if($task)$f['=UF_TASK']=$task;return $this->rows('time',$f,['UF_DATE'=>'DESC','ID'=>'DESC']);}
 public function balance(int $cid,string $m): array {return Policy::balance($this->packages($cid,$m,true),$this->entries($m,$cid));}
 private function base(int $id,int $cid): array {$b=$this->find('packages',$id);if(!$b||(int)$b['UF_CLIENT']!==$cid)throw new \InvalidArgumentException('Пакет другого клиента.');return $b;}
 private function checkTime(int $id,int $cid): void {$cache=[];foreach($this->rows('time',['=UF_PACKAGE'=>$id]) as $e){$m=substr($e['UF_DATE'],0,7);if(!array_key_exists($m,$cache))$cache[$m]=$this->effective($id,$cid,$m);$p=$cache[$m];if(!$p||!in_array((int)$e['UF_DIRECTION'],$p['DIRECTION_IDS'],true))throw new \InvalidArgumentException('Изменение затронет учтённые работы. Сначала перенесите или удалите выполнения.');}}
 public function savePackage(int $id,int $cid,string $m,string $n,int $min,array $ds,bool $repeat,string $end,string $scope,int $u): int {$this->dirs($ds);return $this->tx($cid,function()use($id,$cid,$m,$n,$min,$ds,$repeat,$end,$scope,$u){$v=['UF_NAME'=>$n,'UF_MINUTES'=>$min,'UF_DIRECTION_IDS'=>json_encode(array_values($ds))];if(!$id){if($end!==''&&$end<$m)throw new \InvalidArgumentException('Окончание раньше начала.');return $this->write('packages',$v+['UF_CLIENT'=>$cid,'UF_MONTH'=>$m,'UF_REPEAT'=>$repeat?1:0,'UF_END_MONTH'=>$repeat?$end:'']+$this->stamp($u));}$b=$this->base($id,$cid);if(empty($b['UF_REPEAT'])){if($b['UF_MONTH']!==$m)throw new \InvalidArgumentException('Разовый пакет другого месяца.');if($repeat&&$end!==''&&$end<$m)throw new \InvalidArgumentException('Окончание раньше начала.');$this->write('packages',$v+['UF_REPEAT'=>$repeat?1:0,'UF_END_MONTH'=>$repeat?$end:''],$id);}else{if(!$repeat)throw new \InvalidArgumentException('Остановите пакет через срок.');if(!Policy::effective($b,$m))throw new \InvalidArgumentException('Пакет не действует в месяце.');$old=$this->rows('rules',['=UF_PACKAGE'=>$id,'=UF_MONTH'=>$m,'=UF_SCOPE'=>$scope],['ID'=>'DESC']);$this->write('rules',$v+['UF_PACKAGE'=>$id,'UF_MONTH'=>$m,'UF_SCOPE'=>$scope,'UF_CREATED_AT'=>new DateTime(),'UF_CREATED_BY'=>$u],$old?(int)$old[0]['ID']:0);if($scope==='from')foreach($this->rows('rules',['=UF_PACKAGE'=>$id,'=UF_MONTH'=>$m,'=UF_SCOPE'=>'one']) as $r)$this->remove('rules',(int)$r['ID']);}$this->checkTime($id,$cid);return $id;});}
 public function end(int $id,int $cid,string $end): int {return $this->tx($cid,function()use($id,$cid,$end){$b=$this->base($id,$cid);if(empty($b['UF_REPEAT']))throw new \InvalidArgumentException('Это разовый пакет.');if($end!==''&&$end<$b['UF_MONTH'])throw new \InvalidArgumentException('Окончание раньше начала.');$this->write('packages',['UF_END_MONTH'=>$end],$id);$this->checkTime($id,$cid);return $id;});}
 public function manage(int $id,int $cid,string $m,string $mode): int {if($mode==='finish')return $this->end($id,$cid,$m);return $this->tx($cid,function()use($id,$cid,$m,$mode){$b=$this->base($id,$cid);if($mode==='delete'){if($this->rows('time',['=UF_PACKAGE'=>$id]))throw new \InvalidArgumentException('В пакете есть время. Перенесите выполнения или завершите пакет.');foreach(['rules','skips'] as $t)foreach($this->rows($t,['=UF_PACKAGE'=>$id]) as $r)$this->remove($t,(int)$r['ID']);$this->remove('packages',$id);return $id;}if($mode==='clear'){foreach($this->rows('rules',['=UF_PACKAGE'=>$id,'=UF_MONTH'=>$m,'=UF_SCOPE'=>'one']) as $r)$this->remove('rules',(int)$r['ID']);}else{if(!Policy::effective($b,$m))throw new \InvalidArgumentException('Пакет не действует в месяце.');$ss=$this->rows('skips',['=UF_PACKAGE'=>$id,'=UF_MONTH'=>$m]);if($mode==='skip'&&!$ss)$this->write('skips',['UF_PACKAGE'=>$id,'UF_MONTH'=>$m]);if($mode==='restore')foreach($ss as $r)$this->remove('skips',(int)$r['ID']);}$this->checkTime($id,$cid);return $id;});}
 private function taskRaw(int $id,int $cid,string $n,string $d,string $note,int $dir,string $status,string $m,int $u,array $extra=[]): int {$old=$id?$this->find('tasks',$id):null;if($id&&(!$old||(int)$old['UF_CLIENT']!==$cid))throw new \InvalidArgumentException('Задача другого клиента.');if($old&&(int)$old['UF_DIRECTION']!==$dir&&$this->rows('time',['=UF_TASK'=>$id]))throw new \InvalidArgumentException('У задачи с выполнениями нельзя менять направление.');$done=$status==='done'?($old&&$old['UF_STATUS']==='done'?(string)$old['UF_DONE_MONTH']:date('Y-m')):'';$v=['UF_CLIENT'=>$cid,'UF_NAME'=>$n,'UF_DESCRIPTION'=>$d,'UF_NOTE'=>$note,'UF_DIRECTION'=>$dir,'UF_STATUS'=>$status,'UF_MONTH'=>$m,'UF_DONE_MONTH'=>$done]+$extra;if(!$id)$v+=$this->stamp($u);return $this->write('tasks',$v,$id);}
 public function saveTask(int $id,int $cid,string $n,string $d,string $note,int $dir,string $s,string $m,int $u): int {$this->dirs([$dir]);return $this->tx($cid,function()use($id,$cid,$n,$d,$note,$dir,$s,$m,$u){return $this->taskRaw($id,$cid,$n,$d,$note,$dir,$s,$m,$u);});}
 private function timeRaw(int $id,int $cid,int $task,int $pkg,string $date,int $min,string $d,string $note,int $u,string $token,string $hash=''): int {$old=$id?$this->find('time',$id):null;if($id&&(!$old||(int)$old['UF_CLIENT']!==$cid))throw new \InvalidArgumentException('Выполнение другого клиента.');$t=$this->find('tasks',$task);if(!$t||(int)$t['UF_CLIENT']!==$cid)throw new \InvalidArgumentException('Задача другого клиента.');$v=['UF_CLIENT'=>$cid,'UF_TASK'=>$task,'UF_DIRECTION'=>(int)$t['UF_DIRECTION'],'UF_PACKAGE'=>$pkg,'UF_DATE'=>$date,'UF_MINUTES'=>$min,'UF_DESCRIPTION'=>$d,'UF_NOTE'=>$note];if(!$id){$same=$this->rows('time',['=UF_CLIENT'=>$cid,'=UF_XML_ID'=>'TIME_'.$token]);if($same){foreach($v as $f=>$val)if((string)$same[0][$f]!==(string)$val)throw new \InvalidArgumentException('Запрос уже сохранён с другими данными.');return (int)$same[0]['ID'];}}if($pkg){$p=$this->effective($pkg,$cid,substr($date,0,7));if(!$p||!in_array((int)$t['UF_DIRECTION'],$p['DIRECTION_IDS'],true))throw new \InvalidArgumentException('Пакет не подходит для даты или направления.');}if(!$id){$st=$this->stamp($u);$st['UF_XML_ID']='TIME_'.$token;$v+=$st;$v['UF_REQUEST_HASH']=$hash;}$saved=$this->write('time',$v,$id);if(!$id&&$t['UF_STATUS']==='planned')$this->write('tasks',['UF_STATUS'=>'work','UF_DONE_MONTH'=>''],$task);return $saved;}
 public function saveTime(int $id,int $cid,int $task,int $pkg,string $date,int $min,string $d,string $note,int $u,string $token): int {return $this->tx($cid,function()use($id,$cid,$task,$pkg,$date,$min,$d,$note,$u,$token){return $this->timeRaw($id,$cid,$task,$pkg,$date,$min,$d,$note,$u,$token);});}
 public function saveWork(int $cid,string $name,string $desc,string $note,int $dir,string $s,string $m,bool $plan,string $date,int $min,int $pkg,int $u,string $token,int $preset): array {$this->dirs([$dir]);$tpl=$preset?$this->find('presets',$preset):null;if($preset&&(!$tpl||!$tpl['UF_ACTIVE']))throw new \InvalidArgumentException('Шаблон отключён. Обновите меню.');$group=!$plan&&$tpl&&!empty($tpl['UF_GROUP']);if($group)$s='work';$hash=hash('sha256',json_encode([$cid,$name,$desc,$note,$dir,$s,$m,$plan,$date,$min,$pkg,$preset],JSON_UNESCAPED_UNICODE));return $this->tx($cid,function()use($cid,$name,$desc,$note,$dir,$s,$m,$plan,$date,$min,$pkg,$u,$token,$preset,$group,$hash){if(!$plan){$es=$this->rows('time',['=UF_CLIENT'=>$cid,'=UF_XML_ID'=>'TIME_'.$token]);if($es){if(!hash_equals((string)$es[0]['UF_REQUEST_HASH'],$hash))throw new \InvalidArgumentException('Запрос уже сохранён с другими данными.');return ['task'=>(int)$es[0]['UF_TASK'],'entry'=>(int)$es[0]['ID']];}}$same=$this->rows('tasks',['=UF_CLIENT'=>$cid,'=UF_XML_ID'=>'WORK_'.$token]);if($same){if(!hash_equals((string)$same[0]['UF_REQUEST_HASH'],$hash))throw new \InvalidArgumentException('Запрос уже создал другую работу.');return ['task'=>(int)$same[0]['ID'],'entry'=>0];}$task=0;if($group){$gs=$this->rows('tasks',['=UF_CLIENT'=>$cid,'=UF_DIRECTION'=>$dir,'=UF_TEMPLATE_ID'=>$preset,'=UF_TEMPLATE_GROUP'=>1,'!=UF_STATUS'=>'done'],['ID'=>'DESC']);if($gs)$task=(int)$gs[0]['ID'];}if(!$task)$task=$this->taskRaw(0,$cid,$name,$plan?$desc:'',$plan?$note:'',$dir,$plan?'planned':$s,$m,$u,['UF_XML_ID'=>'WORK_'.$token,'UF_REQUEST_HASH'=>$hash,'UF_TEMPLATE_ID'=>$preset,'UF_TEMPLATE_GROUP'=>$group?1:0]);$entry=$plan?0:$this->timeRaw(0,$cid,$task,$pkg,$date,$min,$desc,$note,$u,$token,$hash);return ['task'=>$task,'entry'=>$entry];});}
 public function deleteTask(int $id,int $cid): int {return $this->tx($cid,function()use($id,$cid){$t=$this->find('tasks',$id);if(!$t||(int)$t['UF_CLIENT']!==$cid)throw new \InvalidArgumentException('Задача не найдена.');if($this->rows('time',['=UF_TASK'=>$id]))throw new \InvalidArgumentException('Сначала удалите или перенесите выполнения.');$this->remove('tasks',$id);return $id;});}
 public function deleteTime(int $id,int $cid): int {return $this->tx($cid,function()use($id,$cid){$e=$this->find('time',$id);if(!$e||(int)$e['UF_CLIENT']!==$cid)throw new \InvalidArgumentException('Выполнение не найдено.');$this->remove('time',$id);return $id;});}
 public function options(int $cid,int $dir,string $date,int $task=0): array {if(!$this->find('clients',$cid))throw new \InvalidArgumentException('Выберите клиента.');if($task){$t=$this->find('tasks',$task);if(!$t||(int)$t['UF_CLIENT']!==$cid)throw new \InvalidArgumentException('Задача другого клиента.');$dir=(int)$t['UF_DIRECTION'];}$this->dirs([$dir]);$a=[];foreach($this->packages($cid,substr($date,0,7)) as $p)if(in_array($dir,$p['DIRECTION_IDS'],true))$a[]=['id'=>(int)$p['ID'],'name'=>$p['UF_NAME'],'minutes'=>(int)$p['UF_MINUTES']];return $a;}
}
